 en = {
  A = {
   { "Hall of Thanes", 13, 18, "go", "14–17", "Handy from Ironforge. Get the Dark Iron Map in Dun Morogh first.", "Ironforge: from the Great Forge toward The High Seat, the web-covered passage on the left (43.5 52.0). Falling is lethal.",
    { { "Important Heirlooms", "Thom Filch, outside the entrance" }, { "The Restless Dead", "Afadra Dunwall, up the stairs from the entrance" }, { "Old Ironforge Incursion", "Dark Iron Map, dropped by a Dark Iron Spy in Dun Morogh" }, { "An Ancient Grudge", "Ghostly Attendant, inside the dungeon" }, { "The Treaty of Understanding", "tablet in the last boss's vault, turn in to King Magni" } },
    {  } },
   { "Ruins of Lordaeron", 15, 20, "opt", "17–19", "Only if you are already nearby: it is far, and rough below 17.", "Outside Undercity, Tirisfal Glades (72.4 11.6): before the keep, up the stairs on the left.",
    { { "Abominable Creatures", "Captain Truman, at the entrance" }, { "Bloodied Insignia", "dropped by undead" }, { "Remember That I Love You", "Crumpled Paper, in Rath'mael's graveyard" }, { "Crest of Lordaeron", "inside the dungeon" } },
    {  } },
   { "The Deadmines", 17, 26, "go", "18–22", "Right after Redridge Mountains: The Defias Brotherhood chain is the richest.", "Westfall, Moonbrook: Defias Hideout (42 72), go through the mine to the portal.",
    { { "Red Silk Bandanas", "Scout Riell, Westfall" }, { "The Defias Brotherhood", "Gryan Stoutmantle, Westfall" }, { "Collecting Memories", "Wilder Thistlenettle, Stormwind" }, { "Oh Brother…", "Wilder Thistlenettle, Stormwind" }, { "Underground Assault", "Shoni the Shilent, Stormwind" }, { "Destruction in Deadmines", "Alba Fairmoon, Westfall" }, { "The Unsent Letter", "An Unsent Letter, dropped in the dungeon" } },
    {  } },
   { "Wailing Caverns", 17, 24, "skip", "", "Too far for the Alliance.", "The Barrens, Lushwater Oasis (46.0 36.3): enter the cave and go down to the portal.",
    { { "Deviate Hides", "Nalpak, The Barrens" }, { "Deviate Eradication", "Ebru, The Barrens" }, { "Trouble at the Docks", "Crane Operator Bigglefuzz, The Barrens" }, { "Smart Drinks", "Mebok Mizzyrix, The Barrens" }, { "The Glowing Shard", "inside the dungeon" } },
    {  } },
   { "Shadowfang Keep", 22, 30, "skip", "", "Far away and without useful quests for the Alliance.", "Silverpine Forest, in the hills north of Pyrewood Village (44.7 67.8).",
    {  },
    { { "The Horn of Xelthos", "rogue", "inside the dungeon, solo" }, { "The Orb of Soran'ruk", "warlock", "inside the dungeon" }, { "The Test of Righteousness", "paladin", "inside the dungeon" } } },
   { "The Stockade", 24, 32, "go", "25–29", "If you collected the quests: quick and easy.", "Stormwind, The Canals near the Mage Quarter (42 58).",
    { { "What Comes Around…", "Guard Berton, Redridge Mountains" }, { "Crime and Punishment", "Councilman Millstipe, Duskwood" }, { "Quell The Uprising", "Warden Thelwater, Stormwind" }, { "The Color of Blood", "Nikova Raskol, Stormwind" }, { "The Fury Runs Deep", "Motley Garmason, Wetlands" }, { "The Stockade Riots", "Warden Thelwater, Stormwind" } },
    {  } },
   { "Blackfathom Deeps", 24, 32, "go", "23–26", "Once, with every quest.", "Ashenvale, Zoram Strand (14.5 14.6): swim through the pool and follow the cave with the elite naga.",
    { { "In Search of Thaelrid", "Dawnwatcher Shaedlass, Darnassus" }, { "Twilight Falls", "Argent Guard Manados, Darnassus" }, { "Knowledge in the Deeps", "Gerrig Bonegrip, Ironforge" }, { "Researching the Corruption", "Gershala Nightwhisper, Darkshore" }, { "Blackfathom Villainy", "Argent Guard Thaelrid, inside the dungeon" } },
    { { "The Orb of Soran'ruk", "warlock", "inside the dungeon" }, { "The Test of Righteousness", "paladin", "inside the dungeon" } } },
